import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"개발 로드맵","description":"","frontmatter":{},"headers":[],"relativePath":"design/Development-Roadmap.md","filePath":"design/Development-Roadmap.md"}'),r={name:"design/Development-Roadmap.md"};function l(i,t,n,s,h,c){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="개발-로드맵" tabindex="-1">개발 로드맵 <a class="header-anchor" href="#개발-로드맵" aria-label="Permalink to &quot;개발 로드맵&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-grammar.svg?raw=true" alt="모든 개발 단계에서 칸에 누가 서 있고 어느 쪽을 보며 어디까지 보이는지"></p><p>이 로드맵은 <a href="/design/Concept.html">Concept.md</a>의 현재 모듈 <code>Unity POC 통합 코어 루프</code>와 <a href="/design/ToDo.html">ToDo.md</a>의 실측 상태를 반영한다. 일정 약속이 아니라 의존성과 실패 기준을 설명한다.</p><h2 id="목표-형태-2026-09-07-소유자-결정" tabindex="-1">목표 형태 (2026-09-07 소유자 결정) <a class="header-anchor" href="#목표-형태-2026-09-07-소유자-결정" aria-label="Permalink to &quot;목표 형태 (2026-09-07 소유자 결정)&quot;">​</a></h2><p>이 게임이 도달하려는 형태는 <strong>4X + RPG</strong>이며 전투는 <strong>실시간 진형·카드 전투</strong>다(<a href="https://github.com/islee23520/seoul-kenshi/blob/main/Intent.md" target="_blank" rel="noreferrer">Intent</a> 결정 3). 기준 레퍼런스는 <a href="/rules/Ref-Songs-of-Silence.html">Songs of Silence</a>(지도 턴 4X + 실시간 자동 전투 + 영웅 카드)이고, 턴제 SRPG 쪽의 정밀 참조는 <a href="/rules/Ref-Ravelen-Chronicles.html">라벨렌 전기</a>다. 계약은 그대로다. 카메라(45/35.264 고정 직교 아이소)·격자(1.5m 4방향)·결정론(동일 seed + 명령 기록)이 유지되고, 바뀌는 것은 <strong>전투 안에서 플레이어가 하는 일</strong>뿐이다.</p><table tabindex="0"><thead><tr><th>층</th><th>목표</th><th>상태</th></tr></thead><tbody><tr><td>4X 전략</td><td>노선·역을 탐상·확장·개발·정복, 제한된 상태 전이로 인과를 읽을 수 있게</td><td>설계 문서 있음, 런타임은 세 역 노선 POC만</td></tr><tr><td>RPG</td><td>인물 성장·관계·생업·직위가 카드와 지휘 반경으로 전투에 들어온다</td><td>인물 원본(412인) 있음, 카드 부여 규칙 미설계</td></tr><tr><td>실시간 진형·카드 전투</td><td>전투 전 진형 편집, 전투 중 카드(일시정지 가능), 사기·항복, 틱 스탬프 명령 기록</td><td>Core 규칙 <code>rtfc-owner-cards-v2</code>(30Hz) 반영. 분대 명령·집계 사상자 표현은 계약 승인, 완료 검증 미완</td></tr></tbody></table><p>목표 형태는 그대로다. 전투 Core는 이미 실시간 진형·카드 규칙으로 바꾸었고, 아래 검증 단계는 시각 수용·슬롯 연결·시각 게이트를 끝내는 순서다.</p><h2 id="현재-완료-poc-슬라이스" tabindex="-1">현재 완료 (POC 슬라이스) <a class="header-anchor" href="#현재-완료-poc-슬라이스" aria-label="Permalink to &quot;현재 완료 (POC 슬라이스)&quot;">​</a></h2><ul><li>Foundation 기반: Bootstrap App scope/FSM, 배타적 화면 lease, VContainer 정적 계약, 아키텍처 게이트</li><li>코어 루프(ToDo 5–12): 결정론 Core ID·tick·명령·RNG 스트림·원장 해시, 영등포–신도림–구로 세 역 노선, 교섭·우회를 포함한 여섯 단계 캠페인, 30Hz 실시간 진형·카드 전투(<code>rtfc-owner-cards-v2</code>), 정확히 한 번 정산, MainTitle 포함 uGUI 화면 — batchmode PlayMode로 동일 seed 재현·중복 정산 거부 검증</li><li>생성 아트 기반: 역사 소품 6종 source-bound BOM 승격·런타임 연결, 3역할(탐사원·의무원·순찰대) 캐릭터 승격, UI kit 9종 후보(시각 수용 대기), TRELLIS v1 옵션 호스트 계약 고정</li><li>세계관·인물 원본: 국가별 명부(Cast-State-01–16, 412인)와 관계 원장, 적대 집단 G01–G27 게시, 서사 배치 B001–B047, ISO 세계·가문·적대 도표, 몬스터 배치 원장 M001–M042, World-Narrative-Atlas 통합</li><li>공개 Wiki: docs/game-logic 원본의 자동 생성 미러가 원본 커밋과 동기(소스 페이지 188, 미게시 조각은 표로만 추적)</li><li>저장소 검증 도구: LFS 사전 스머지 검사, Cast-Index 관계 수(송신 간선) 계약 검증, 위키 빌더의 미게시 조각 누출 방지, 신규 클론 PlayMode 준비 절차</li></ul><h2 id="다음-검증-단계-순서-의존" tabindex="-1">다음 검증 단계 (순서 의존) <a class="header-anchor" href="#다음-검증-단계-순서-의존" aria-label="Permalink to &quot;다음 검증 단계 (순서 의존)&quot;">​</a></h2><ol><li>시각 수용 — 타이틀(#8)과 UI kit·아이콘·타일(#23)의 4축 독립 재심사와 소유자 육안 승인. COMPOSITION·PRODUCT_POLISH raw FAIL은 면제 없음. 캐릭터는 기존 placeholder가 폐기됐으므로 TOS식 SD 재작업(#58)이 선행된다</li><li>UI 마무리 — uGUI HUD·진형 편집·지휘관 카드는 연결됨. 안정 요소 이름·씬 흐름·결정론 계약을 유지한 채 시각 수용·슬롯 연결(#59 잔여·ToDo 18)</li><li>슬롯 연결(ToDo 16, #26) — 승격된 에셋만 uGUI 런타임 슬롯에 연결하고 임시 비주얼 제거</li><li>최종 수용 게이트(ToDo 17, #27) — 아키텍처 게이트, batchmode PlayMode 전 경로, 4축 시각 PASS, BOM fail-closed, 동일 Unity revision macOS Development player smoke, 임시 리소스 cleanup receipt를 한 번에 통과</li><li>서사·협업 후속(#41) — 외부 기여자와의 서사 디렉션 역할·경계 합의</li><li>전투 표현 마무리 — Core는 <code>rtfc-owner-cards-v2</code>로 반영됐다. 남은 일은 <a href="/rules/Realtime-Formation-Card-Battle.html">실시간 진형·카드 전투</a>의 분대 명령·집계 사상자 검증, Foundation HUD 잔여, BOM 승격 슬롯 연결이다. POC 비주얼은 오드랜드 기증 패이로드(<code>Game/Assets/Quarantine/Oddland/</code>, <a href="/design/Asset-Pipeline.html">에셋이 들어오는 길</a> 기증 절)의 3D·SFX·VFX와 Spine POC 캐릭터를 쓰되, 런타임 슬롯 연결은 BOM 승격 게이트를 그대로 통과해야 한다. 전체 16국·412인 캠페인, 저장·외교·공성은 그 뒤 별도 모듈</li></ol><p>각 단계는 실패하면 다음 단계로 넘어가지 않는다.</p><h2 id="검증-게이트" tabindex="-1">검증 게이트 <a class="header-anchor" href="#검증-게이트" aria-label="Permalink to &quot;검증 게이트&quot;">​</a></h2><table tabindex="0"><thead><tr><th>게이트</th><th>통과 조건</th></tr></thead><tbody><tr><td>시뮬레이션</td><td>100개 고정 시드를 두 번 실행해 상태·원장 해시 일치</td></tr><tr><td>지도</td><td>경로, 층, 환승과 봉쇄를 잘못 해석하지 않음</td></tr><tr><td>전투 왕복</td><td>중복 정산 0건, 저장 경계 복원 성공</td></tr><tr><td>캐릭터</td><td>실제 Play Mode 캡처에서 중대 가림·방향·경계 결함 0건</td></tr><tr><td>시각</td><td>COMPOSITION / SPRITE_FIDELITY / TYPOGRAPHY / PRODUCT_POLISH 독립 PASS</td></tr><tr><td>자산</td><td>출시 후보의 권리·도구·변환 BOM 누락 0건</td></tr><tr><td>빌드</td><td>고정 Unity revision에서 컴파일, 테스트와 대상 빌드 성공</td></tr></tbody></table><p>POC 슬라이스가 위 게이트를 모두 통과하기 전까지 두 번째 제품 모듈을 시작하지 않는다.</p>',15)])])}const P=e(r,[["render",l]]);export{p as __pageData,P as default};
